//! Adds OpenCode's per-conversation cache key to every Rig request.

use bytes::Bytes;
use rig::{
    http_client::{HttpClientExt, LazyBody, MultipartForm, Request, Response, StreamingResponse},
    wasm_compat::WasmCompatSend,
};

#[derive(Clone, Debug)]
pub struct SessionTransport<H> {
    inner: H,
    session: rig::http_client::HeaderValue,
}

impl<H> SessionTransport<H> {
    pub fn new(inner: H, session: &str) -> Self {
        Self {
            inner,
            // Conversation IDs are UUIDs generated by this service, so they are
            // always valid HTTP header values.
            session: session
                .parse()
                .expect("conversation UUID is a header value"),
        }
    }
}

impl<H: Default> Default for SessionTransport<H> {
    fn default() -> Self {
        Self {
            inner: H::default(),
            // Required by Rig's generic model bound. Real clients always use
            // `new`; this sentinel prevents accidental cache sharing.
            session: rig::http_client::HeaderValue::from_static("missing-session"),
        }
    }
}

impl<H: HttpClientExt> SessionTransport<H> {
    fn with_session<T>(&self, mut request: Request<T>) -> Request<T> {
        request
            .headers_mut()
            .insert("x-opencode-session", self.session.clone());
        request
    }
}

impl<H: HttpClientExt> HttpClientExt for SessionTransport<H> {
    fn send<T, U>(
        &self,
        request: Request<T>,
    ) -> impl std::future::Future<Output = rig::http_client::Result<Response<LazyBody<U>>>>
    + WasmCompatSend
    + 'static
    where
        T: Into<Bytes> + WasmCompatSend,
        U: From<Bytes> + WasmCompatSend + 'static,
    {
        self.inner.send(self.with_session(request))
    }

    fn send_multipart<U>(
        &self,
        request: Request<MultipartForm>,
    ) -> impl std::future::Future<Output = rig::http_client::Result<Response<LazyBody<U>>>>
    + WasmCompatSend
    + 'static
    where
        U: From<Bytes> + WasmCompatSend + 'static,
    {
        self.inner.send_multipart(self.with_session(request))
    }

    fn send_streaming<T>(
        &self,
        request: Request<T>,
    ) -> impl std::future::Future<Output = rig::http_client::Result<StreamingResponse>> + WasmCompatSend
    where
        T: Into<Bytes> + WasmCompatSend,
    {
        self.inner.send_streaming(self.with_session(request))
    }
}
